"""Bloom filter with empirically-checked math. Python stdlib only."""

import math
import struct
from hashlib import blake2b


class BloomFilter:
    """Classic Bloom filter using double hashing over two BLAKE2b-derived
    64-bit values: h_i(x) = (h1(x) + i * h2(x)) mod m, for i in 0..k-1.

    Sizing follows the standard optimal formulas:
        m = -n * ln(p) / (ln 2)^2      (optimal bit count)
        k = (m / n) * ln 2             (optimal number of hash functions)
    """

    __slots__ = ("m", "k", "bits")

    def __init__(self, m: int, k: int):
        if m <= 0:
            raise ValueError("m must be positive")
        if k <= 0:
            raise ValueError("k must be positive")
        self.m = m
        self.k = k
        self.bits = bytearray((m + 7) // 8)

    # ------------------------------------------------------------------ #
    # Construction
    # ------------------------------------------------------------------ #
    @classmethod
    def from_capacity(cls, n: int, fp_rate: float) -> "BloomFilter":
        """Size the filter optimally for n expected items at fp_rate."""
        if n <= 0:
            raise ValueError("n must be positive")
        if not 0.0 < fp_rate < 1.0:
            raise ValueError("fp_rate must be in (0, 1)")
        m_float = -n * math.log(fp_rate) / (math.log(2) ** 2)
        m = max(1, math.ceil(m_float))
        k = max(1, round((m / n) * math.log(2)))
        return cls(m, k)

    # ------------------------------------------------------------------ #
    # Hashing
    # ------------------------------------------------------------------ #
    @staticmethod
    def _hash64(item: str) -> tuple[int, int]:
        """Two independent-ish 64-bit values from BLAKE2b."""
        data = item.encode("utf-8")
        digest = blake2b(data, digest_size=16).digest()
        h1, h2 = struct.unpack(">QQ", digest)
        return h1, h2

    def _positions(self, item: str):
        h1, h2 = self._hash64(item)
        # Ensure a nonzero stride so all k probes aren't identical.
        h2 |= 1
        m = self.m
        return ((h1 + i * h2) % m for i in range(self.k))

    # ------------------------------------------------------------------ #
    # Core operations
    # ------------------------------------------------------------------ #
    def add(self, item: str) -> None:
        bits = self.bits
        for pos in self._positions(item):
            bits[pos >> 3] |= 1 << (pos & 7)

    def __contains__(self, item: str) -> bool:
        bits = self.bits
        return all(bits[pos >> 3] & (1 << (pos & 7)) for pos in self._positions(item))

    # ------------------------------------------------------------------ #
    # Introspection
    # ------------------------------------------------------------------ #
    def popcount(self) -> int:
        """Number of set bits."""
        return sum(byte.bit_count() for byte in self.bits)

    def estimated_fp_rate(self) -> float:
        """Estimated false-positive rate from the fraction of zero bits:

            p ~= (1 - e^(-k*n/m))^k = (1 - frac_zero)^k = (frac_ones)^k
        """
        frac_ones = self.popcount() / self.m
        if frac_ones >= 1.0:
            return 1.0
        return frac_ones ** self.k

    # ------------------------------------------------------------------ #
    # Set operations
    # ------------------------------------------------------------------ #
    def _assert_same_shape(self, other: "BloomFilter") -> None:
        if self.m != other.m or self.k != other.k:
            raise ValueError("filters must have the same shape (m, k)")

    def union(self, other: "BloomFilter") -> "BloomFilter":
        """Return a new filter whose membership is the union of both."""
        self._assert_same_shape(other)
        result = BloomFilter(self.m, self.k)
        result.bits = bytearray(a | b for a, b in zip(self.bits, other.bits))
        return result

    def union_inplace(self, other: "BloomFilter") -> None:
        self._assert_same_shape(other)
        for i, b in enumerate(other.bits):
            self.bits[i] |= b

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, BloomFilter):
            return NotImplemented
        return self.m == other.m and self.k == other.k and self.bits == other.bits

    def __repr__(self) -> str:
        return f"BloomFilter(m={self.m}, k={self.k})"

import random
import string

import pytest

from bloom import BloomFilter


def random_strings(n: int, seed: int) -> list[str]:
    rng = random.Random(seed)
    alphabet = string.ascii_letters + string.digits + string.punctuation
    out = []
    for _ in range(n):
        length = rng.randint(5, 40)
        out.append("".join(rng.choice(alphabet) for _ in range(length)))
    return out


@pytest.fixture(scope="module")
def inserted():
    return random_strings(20000, seed=42)


@pytest.fixture(scope="module")
def probe_strings():
    return random_strings(50000, seed=12345)


@pytest.fixture(scope="module")
def bf(inserted):
    f = BloomFilter.from_capacity(20000, 0.01)
    for s in inserted:
        f.add(s)
    return f


class TestZeroFalseNegatives:
    def test_all_inserted_found(self, bf, inserted):
        assert len(inserted) == 20000
        misses = [s for s in inserted if s not in bf]
        assert misses == []

    def test_no_false_negatives_across_many_shapes(self):
        for seed in range(5):
            items = random_strings(1000, seed=seed)
            for cap, fp in [(1000, 0.01), (1000, 0.05), (500, 0.02)]:
                f = BloomFilter.from_capacity(cap, fp)
                for s in items[:cap]:
                    f.add(s)
                assert all(s in f for s in items[:cap])


class TestFalsePositiveRate:
    def test_empirical_fp_within_2x_of_requested(self, bf, inserted, probe_strings):
        assert bf.fp_request_check if False else True  # noqa: B011
        # Remove accidental collisions between probe set and inserted set.
        inserted_set = set(inserted)
        fresh = [s for s in probe_strings if s not in inserted_set]
        fps = sum(s in bf for s in fresh)
        measured = fps / len(fresh)
        # Requested 1%; allow up to 2x.
        assert measured < 0.02, (
            f"measured fp rate {measured:.4f} exceeds 2x requested (0.02)"
        )
        # Sanity floor: a working filter shouldn't have ~zero discrimination,
        # but keep this loose to avoid flakiness.
        assert measured > 0.0

    def test_sizing_math_matches_formulas(self):
        f = BloomFilter.from_capacity(20000, 0.01)
        import math

        expected_m = math.ceil(-20000 * math.log(0.01) / (math.log(2) ** 2))
        expected_k = round((expected_m / 20000) * math.log(2))
        assert f.m == expected_m
        assert f.k == expected_k


class TestUnion:
    def test_union_behaves_like_inserting_both_sets(self, inserted, probe_strings):
        f1 = BloomFilter.from_capacity(40000, 0.01)
        f2 = BloomFilter.from_capacity(40000, 0.01)
        half = len(inserted) // 2
        for s in inserted[:half]:
            f1.add(s)
        for s in probe_strings[:half]:
            f2.add(s)

        combined_direct = BloomFilter.from_capacity(40000, 0.01)
        for s in inserted[:half] + probe_strings[:half]:
            combined_direct.add(s)

        merged = f1.union(f2)
        assert merged == combined_direct

        # Membership semantics: everything from either filter is present.
        for s in inserted[:half]:
            assert s in merged
        for s in probe_strings[:half]:
            assert s in merged
        assert all(
            (s in merged) == (s in f1 or s in f2)
            for s in random_strings(2000, seed=777)
        )

    def test_union_inplace(self, inserted, probe_strings):
        f1 = BloomFilter.from_capacity(40000, 0.01)
        f2 = BloomFilter.from_capacity(40000, 0.01)
        half = 5000
        for s in inserted[:half]:
            f1.add(s)
        for s in probe_strings[:half]:
            f2.add(s)
        expected = f1.union(f2)
        f1.union_inplace(f2)
        assert f1 == expected

    def test_union_shape_mismatch_raises(self, inserted):
        f1 = BloomFilter.from_capacity(1000, 0.01)
        f2 = BloomFilter.from_capacity(2000, 0.01)
        with pytest.raises(ValueError):
            f1.union(f2)
        with pytest.raises(ValueError):
            f1.union_inplace(f2)


class TestEstimatedFpRate:
    def test_estimate_within_2x_of_measured(self, bf, inserted, probe_strings):
        inserted_set = set(inserted)
        fresh = [s for s in probe_strings if s not in inserted_set]
        measured = sum(s in bf for s in fresh) / len(fresh)
        estimate = bf.estimated_fp_rate()

        # Both are approximations of ~1%; they should agree within 2x.
        lo, hi = sorted((measured, estimate))
        assert hi < 2 * lo, (
            f"estimated {estimate:.4f} vs measured {measured:.4f}"
        )

    def test_empty_filter_estimates_zero(self):
        f = BloomFilter.from_capacity(1000, 0.01)
        assert f.estimated_fp_rate() == 0.0

    def test_full_filter_estimates_one(self):
        f = BloomFilter(10, 3)
        for i in range(10):
            f.add(str(i))
        # Force every bit set.
        f.bits = bytearray(b"\xff" * len(f.bits))
        assert f.estimated_fp_rate() == 1.0

